CREATE OR REPLACE PROCEDURE archive_old_orders (
    p_order_date IN DATE
)
AS
    TYPE t_orders IS TABLE OF HARNESS_APP.ORDERS%ROWTYPE;
    l_orders t_orders;

    CURSOR c_old_orders IS
        SELECT *
        FROM   HARNESS_APP.ORDERS
        WHERE  ORDER_DATE < p_order_date;
BEGIN
    OPEN c_old_orders;

    LOOP
        FETCH c_old_orders BULK COLLECT INTO l_orders LIMIT 10000;

        EXIT WHEN l_orders.COUNT = 0;

        FORALL i IN INDICES OF l_orders
            INSERT INTO HARNESS_APP.ORDERS_ARCHIVE (
                ORDER_ID,
                CUSTOMER_ID,
                ORDER_DATE,
                STATUS,
                TOTAL
            )
            VALUES (
                l_orders(i).ORDER_ID,
                l_orders(i).CUSTOMER_ID,
                l_orders(i).ORDER_DATE,
                l_orders(i).STATUS,
                l_orders(i).TOTAL
            );

        FORALL i IN INDICES OF l_orders
            DELETE FROM HARNESS_APP.ORDERS
            WHERE  ORDER_ID = l_orders(i).ORDER_ID;
    END LOOP;

    CLOSE c_old_orders;
END archive_old_orders;
/
```

Assumptions:

- “Older than a given date” is implemented as `ORDER_DATE < p_order_date`. If you want to include the supplied date, change the predicate to `ORDER_DATE <= p_order_date`.
- The procedure does not commit or roll back. The caller controls transaction completion.
- The archive insert names the columns explicitly because the context says `ORDERS_ARCHIVE` has the same columns as `ORDERS`, but it does not guarantee column order.
- Batch order is not specified. If deterministic batch order is required, add `ORDER BY ORDER_ID` to the cursor; `ORDER_ID` is the primary key, so there are no ties on that ordering.

