DECLARE
  l_failures            NUMBER := 0;
  l_existing_dept_id    NUMBER;
  l_expected_existing   NUMBER;
  l_actual_existing     NUMBER;

  l_no_match_dept_id    NUMBER := -1;
  l_no_match_rows       NUMBER;
  l_expected_no_match   NUMBER;
  l_actual_no_match     NUMBER;

  l_expected_null       NUMBER;
  l_actual_null         NUMBER;
BEGIN
  SAVEPOINT test_savepoint;

  DBMS_OUTPUT.PUT_LINE('Testing HARNESS_APP.headcount');

  -- Check 1: a department_id that matches at least one row.
  SELECT MAX(department_id)
    INTO l_existing_dept_id
    FROM employees
   WHERE department_id IS NOT NULL;

  IF l_existing_dept_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL existing-department check: no non-NULL department_id found in employees.'
    );
    DBMS_OUTPUT.PUT_LINE('Expected: a count greater than 0; Actual: not tested');
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_existing
      FROM employees
     WHERE department_id = l_existing_dept_id;

    l_actual_existing := harness_app.headcount(l_existing_dept_id);

    IF l_actual_existing = l_expected_existing THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS existing-department check: department_id=' ||
        TO_CHAR(l_existing_dept_id) ||
        ', expected=' || TO_CHAR(l_expected_existing) ||
        ', actual=' || TO_CHAR(l_actual_existing)
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL existing-department check: department_id=' ||
        TO_CHAR(l_existing_dept_id) ||
        ', expected=' || TO_CHAR(l_expected_existing) ||
        ', actual=' || TO_CHAR(l_actual_existing)
      );
      l_failures := l_failures + 1;
    END IF;
  END IF;

  -- Check 2: a numeric department_id that matches no rows.
  SELECT COUNT(*)
    INTO l_no_match_rows
    FROM employees
   WHERE department_id = l_no_match_dept_id;

  IF l_no_match_rows <> 0 THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL no-match-department check: department_id=' ||
      TO_CHAR(l_no_match_dept_id) ||
      ' is not a suitable no-match value; rows found=' ||
      TO_CHAR(l_no_match_rows)
    );
    DBMS_OUTPUT.PUT_LINE('Expected: 0; Actual: not tested');
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_no_match
      FROM employees
     WHERE department_id = l_no_match_dept_id;

    l_actual_no_match := harness_app.headcount(l_no_match_dept_id);

    IF l_actual_no_match = l_expected_no_match THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS no-match-department check: department_id=' ||
        TO_CHAR(l_no_match_dept_id) ||
        ', expected=' || TO_CHAR(l_expected_no_match) ||
        ', actual=' || TO_CHAR(l_actual_no_match)
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL no-match-department check: department_id=' ||
        TO_CHAR(l_no_match_dept_id) ||
        ', expected=' || TO_CHAR(l_expected_no_match) ||
        ', actual=' || TO_CHAR(l_actual_no_match)
      );
      l_failures := l_failures + 1;
    END IF;
  END IF;

  -- Check 3: NULL argument. The function compares department_id = p_department_id,
  -- so a NULL argument should match no rows and return 0.
  SELECT COUNT(*)
    INTO l_expected_null
    FROM employees
   WHERE department_id = CAST(NULL AS NUMBER);

  l_actual_null := harness_app.headcount(NULL);

  IF l_actual_null = l_expected_null THEN
    DBMS_OUTPUT.PUT_LINE(
      'PASS NULL-argument check: expected=' || TO_CHAR(l_expected_null) ||
      ', actual=' || TO_CHAR(l_actual_null)
    );
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'FAIL NULL-argument check: expected=' || TO_CHAR(l_expected_null) ||
      ', actual=' || TO_CHAR(l_actual_null)
    );
    l_failures := l_failures + 1;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Failure count: ' || TO_CHAR(l_failures));

  ROLLBACK TO test_savepoint;

  IF l_failures > 0 THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'headcount test block failed with ' || TO_CHAR(l_failures) || ' failure(s)'
    );
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO test_savepoint;
    RAISE;
END;
/
```

The block calls `HARNESS_APP.headcount` by name rather than copying the function into the block. It checks three cases:

1. **Existing department check**: it looks for a non-NULL `department_id` in `employees`, computes the expected count independently with `COUNT(*)`, calls `headcount`, and compares the result. If no suitable `department_id` exists, it prints `FAIL` and counts that as a failure.

2. **No-match department check**: it uses `-1` as a candidate value that should match no rows, confirms with `COUNT(*)` that no rows match, computes the expected count independently, calls `headcount`, and compares the result. If `-1` is not actually a no-match value in this data, it prints `FAIL` and counts that as a failure.

3. **NULL argument check**: it computes the expected result using the same equality comparison the function uses, `department_id = NULL`, which matches no rows, so the expected result is `0`. It calls `headcount(NULL)` and compares the actual result.

The block starts with `SAVEPOINT test_savepoint` and ends with `ROLLBACK TO test_savepoint`, so it does not commit. If any check fails, it raises an application error after rolling back to the savepoint. Its exception handler prints unexpected errors, rolls back to the savepoint, and re-raises the error. I have not run this block.

